&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;SqlQuery&quot;:&quot;DELETE FROM app.Imputatie\nWHERE \n    Luna = @Luna\n    AND Anul = @Anul\n    AND CodSucursala = @CodSucursala\n    AND Status = 5   --  DOAR cele generate;\n    \nINSERT INTO app.Imputatie (\n    Marca,\n    CodBeneficiar,\n    Rata,\n    Dobanda,\n    Restanta,\n    FondRetinere,\n    Luna,\n    Anul,\n    Judet,\n    CodSucursala,\n    Status,\n    CreatedBy,\n    CreatedDate,\n    LastModifiedBy,\n    LastModifiedDate\n)\nSELECT \n    i.Marca,\n    i.CodBeneficiar,\n\n    CASE \n        WHEN i.Rata &amp;gt; i.FondRetinere THEN i.FondRetinere\n        ELSE i.Rata\n    END,\n\n    i.Dobanda,\n    i.Restanta,\n\n    CASE \n        WHEN i.FondRetinere - i.Rata &amp;lt; 0 THEN 0\n        ELSE i.FondRetinere - i.Rata\n    END,\n\n    @Luna,\n    @Anul,\n\n    s.Judet,\n\n    @CodSucursala,\n\n    5,\n\n    --  FIX AICI\n    ISNULL(i.CreatedBy, @UserId),\n    ISNULL(i.CreatedDate, GETDATE()),\n    @UserId,\n    GETDATE()\n\nFROM app.Imputatie i\n\nJOIN app.Salariat s \n    ON s.Marca = i.Marca \n    AND s.CodSucursala = i.CodSucursala\n    AND s.Anul = i.Anul\n    AND s.Luna = i.Luna\n\nWHERE \n    i.CodSucursala = @CodSucursala\n\n    AND i.Luna = CASE \n                    WHEN @Luna = 1 THEN 12\n                    ELSE @Luna - 1\n                 END\n                 \n    AND i.Anul = CASE \n                    WHEN @Luna = 1 THEN @Anul - 1\n                    ELSE @Anul\n                 END\n\n    AND i.FondRetinere &amp;gt; 0\n\n    AND NOT EXISTS (\n        SELECT 1 \n        FROM app.Imputatie x\n        WHERE \n            x.Marca = i.Marca\n            AND x.CodBeneficiar = i.CodBeneficiar\n            AND x.Luna = @Luna\n            AND x.Anul = @Anul\n            AND x.CodSucursala = @CodSucursala\n    )&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOr